### 🛠️ Production Implementation & Technical Verification

1. **Root Cause Analysis & Architectural Design**:

`POST /api/reviews` persists `req.body` without establishing a trust boundary. This permits invalid ratings, missing identifiers, unbounded comments, unexpected fields, and special keys such as `__proto__` to enter the in-memory store.

The fix validates at the controller boundary before `createReview` executes. A strict Zod object schema:

- permits only `reviewerId`, `targetId`, `rating`, and optional `comment`;
- requires trimmed non-empty IDs;
- accepts integer ratings only from 1 through 5;
- trims comments and bounds them to 1–2000 characters when supplied;
- rejects unknown and prototype-pollution keys;
- returns a deterministic `400` without invoking persistence.

2. **Production-Grade Implementation Source Code**:

### Production Source (`apps/api/src/validators/review.js`)

```js
import { z } from "zod";

const reviewIdSchema = z
  .string()
  .trim()
  .min(1, "Must not be empty.")
  .max(128, "Must not exceed 128 characters.");

export const createReviewSchema = z
  .object({
    reviewerId: reviewIdSchema,
    targetId: reviewIdSchema,
    rating: z
      .number({
        required_error: "rating is required.",
        invalid_type_error: "rating must be a number.",
      })
      .int("rating must be an integer.")
      .min(1, "rating must be between 1 and 5.")
      .max(5, "rating must be between 1 and 5."),
    comment: z
      .string({
        invalid_type_error: "comment must be a string.",
      })
      .trim()
      .min(1, "comment must not be empty.")
      .max(2000, "comment must not exceed 2000 characters.")
      .optional(),
  })
  .strict();
```

### Production Source (`apps/api/src/controllers/reviewController.js`)

```js
import { createReview, listReviews } from "../services/reviewService.js";
import { createReviewSchema } from "../validators/review.js";

function validationErrorResponse(error) {
  return {
    error: "Invalid review payload.",
    details: error.issues.map((issue) => ({
      field: issue.path.join(".") || "body",
      message: issue.message,
    })),
  };
}

export function createReviewController(req, res) {
  const parsedPayload = createReviewSchema.safeParse(req.body);

  if (!parsedPayload.success) {
    return res.status(400).json(validationErrorResponse(parsedPayload.error));
  }

  const review = createReview(parsedPayload.data);
  return res.status(201).json(review);
}

export function listReviewsController(req, res) {
  return res.status(200).json(listReviews());
}
```

### Production Source (`apps/api/src/routes/reviewRoutes.js`)

```js
import { Router } from "express";
import {
  createReviewController,
  listReviewsController,
} from "../controllers/reviewController.js";

export const reviewRoutes = Router();

reviewRoutes.post("/", createReviewController);
reviewRoutes.get("/", listReviewsController);
```

3. **Comprehensive Unit Test Suite & Verification Harness**:

### Test Suite (`apps/api/src/tests/reviewValidation.test.js`)

```js
import assert from "node:assert/strict";
import { after, before, test } from "node:test";
import { createApp } from "../app.js";

let server;
let baseUrl;

before(async () => {
  const app = createApp();

  await new Promise((resolve) => {
    server = app.listen(0, "127.0.0.1", resolve);
  });

  const { port } = server.address();
  baseUrl = `http://127.0.0.1:${port}`;
});

after(async () => {
  await new Promise((resolve, reject) => {
    server.close((error) => (error ? reject(error) : resolve()));
  });
});

async function postReview(payload) {
  const response = await fetch(`${baseUrl}/api/reviews`, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify(payload),
  });

  return {
    status: response.status,
    body: await response.json(),
  };
}

test("POST /api/reviews persists a valid, normalized review", async () => {
  const result = await postReview({
    reviewerId: "  reviewer-42  ",
    targetId: "  target-17  ",
    rating: 5,
    comment: "  Excellent delivery and communication.  ",
  });

  assert.equal(result.status, 201);
  assert.equal(result.body.reviewerId, "reviewer-42");
  assert.equal(result.body.targetId, "target-17");
  assert.equal(result.body.rating, 5);
  assert.equal(result.body.comment, "Excellent delivery and communication.");
});

test("POST /api/reviews rejects ratings outside the accepted 1-5 range", async () => {
  for (const rating of [-1, 0, 6, 5.5]) {
    const result = await postReview({
      reviewerId: "reviewer-42",
      targetId: "target-17",
      rating,
    });

    assert.equal(result.status, 400);
    assert.equal(result.body.error, "Invalid review payload.");
    assert.ok(result.body.details.some((detail) => detail.field === "rating"));
  }
});

test("POST /api/reviews rejects missing required identifiers", async () => {
  const missingReviewer = await postReview({
    targetId: "target-17",
    rating: 4,
  });

  assert.equal(missingReviewer.status, 400);
  assert.ok(
    missingReviewer.body.details.some(
      (detail) => detail.field === "reviewerId",
    ),
  );

  const missingTarget = await postReview({
    reviewerId: "reviewer-42",
    rating: 4,
  });

  assert.equal(missingTarget.status, 400);
  assert.ok(
    missingTarget.body.details.some((detail) => detail.field === "targetId"),
  );
});

test("POST /api/reviews rejects unknown and prototype-pollution properties", async () => {
  const payload = JSON.parse(`
    {
      "reviewerId": "reviewer-42",
      "targetId": "target-17",
      "rating": 4,
      "admin": true,
      "__proto__": { "polluted": true }
    }
  `);

  const result = await postReview(payload);

  assert.equal(result.status, 400);
  assert.equal(result.body.error, "Invalid review payload.");
  assert.ok(
    result.body.details.some((detail) => detail.field === "body"),
  );
  assert.equal({}.polluted, undefined);
});

test("POST /api/reviews rejects empty and oversized comments", async () => {
  const emptyComment = await postReview({
    reviewerId: "reviewer-42",
    targetId: "target-17",
    rating: 4,
    comment: "   ",
  });

  assert.equal(emptyComment.status, 400);

  const oversizedComment = await postReview({
    reviewerId: "reviewer-42",
    targetId: "target-17",
    rating: 4,
    comment: "x".repeat(2001),
  });

  assert.equal(oversizedComment.status, 400);
});
```

Execute from the repository root:

```bash
npm test -w apps/api -- reviewValidation.test.js
```

